import AppKit
import BPCore

/// What the status bar shows about the current document.
struct DocumentStatus: Equatable {
    /// 1-based. 0 when not applicable (images).
    var page: Int = 0
    var pageCount: Int = 0
    /// 1.0 = 100%.
    var zoom: Double = 1
    /// Short flags such as "recolor", "trim", "dual", tool names.
    var flags: [String] = []
    /// e.g. "3/17" search matches, or image pixel size. Empty when unused.
    var detail: String = ""
    /// How far down the document the viewport is, 0–100 (zathura's position
    /// percentage). Nil when everything fits or for documents without pages.
    var position: Int?
}

/// One open document (a PDF or an image). Lives inside a window.
/// Implementations: `PDFDocumentController`, `ImageDocumentController`.
@MainActor
protocol DocumentController: AnyObject {
    var fileURL: URL { get }
    /// The view the window embeds. Must be stable for the controller's life.
    var view: NSView { get }
    var host: DocumentHost? { get set }
    var status: DocumentStatus { get }
    var isDirty: Bool { get }
    /// Undo stack for edits. The window forwards its undo manager here.
    var undoManager: UndoManager { get }

    /// Performs a document-level action. Returns false if this controller does
    /// not handle the action (the host then reports "not available").
    @discardableResult
    func perform(_ invocation: ActionInvocation) -> Bool

    /// Called once after creation and again whenever config or theme changes.
    /// Must be cheap when nothing relevant changed.
    func apply(options: Options, theme: Theme)

    /// Re-read the file from disk, keeping page/zoom/scroll position.
    func reloadFromDisk()

    /// Save to `url`, or in place when nil.
    func save(to url: URL?) throws

    /// The view that should be first responder in normal mode.
    var preferredFirstResponder: NSView { get }

    /// Where the viewport is now (for marks and the jump list).
    var currentPosition: DocumentPosition { get }

    /// Move to a position. Does NOT record a jump; the caller does that.
    func go(to position: DocumentPosition, animated: Bool)

    /// Direction of the last `/` or `?`; `search-next` follows it.
    var searchDirectionBackward: Bool { get set }

    /// Table of contents, flattened, for the quick-open palette.
    var outline: [OutlineEntry] { get }
}

struct OutlineEntry {
    var title: String
    /// Nesting depth, 0 = top level.
    var level: Int
    var position: DocumentPosition
}

/// Defaults for documents without pages (images).
extension DocumentController {
    var currentPosition: DocumentPosition { DocumentPosition(page: 0) }
    func go(to position: DocumentPosition, animated: Bool) {}
    var searchDirectionBackward: Bool {
        get { false }
        set {}
    }
    var outline: [OutlineEntry] { [] }
}

/// What a document can ask of the window that hosts it.
@MainActor
protocol DocumentHost: AnyObject {
    var options: Options { get }
    var theme: Theme { get }
    var mode: Mode { get }

    /// Switch input mode, e.g. `.insert` when a form field gains focus and
    /// `.normal` when it loses it.
    func setMode(_ mode: Mode)

    /// Route an action through the normal dispatch path (window-level actions
    /// first, then the document).
    func dispatch(_ invocation: ActionInvocation)

    /// The document's `status` or `isDirty` changed; refresh chrome.
    func documentStatusDidChange()

    /// Show a transient message in the status bar.
    func showMessage(_ text: String, isError: Bool)

    /// The document is about to make a non-incremental jump (gg, G, goto-page,
    /// search hit, link click) away from `position`; push it on the jump list.
    func recordJump(from position: DocumentPosition)
}

/// Shared, app-wide configuration state. Posts `didChange` when the rc is
/// reloaded, an option is set from the command line, or the system appearance
/// flips while `theme` is "auto".
@MainActor
final class AppEnvironment {
    static let shared = AppEnvironment()
    static let didChange = Notification.Name("BPAppEnvironmentDidChange")

    private(set) var config = Config()
    private(set) var theme: Theme = .fallbackDark

    var options: Options { config.options }

    func update(config: Config, theme: Theme) {
        self.config = config
        self.theme = theme
        NotificationCenter.default.post(name: Self.didChange, object: self)
    }
}

extension RGBA {
    var nsColor: NSColor {
        NSColor(srgbRed: r, green: g, blue: b, alpha: a)
    }

    var cgColor: CGColor {
        CGColor(srgbRed: r, green: g, blue: b, alpha: a)
    }
}
